create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.BESCH_LIEF_WA_WG_SUM (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup ID wird verwendet für Beziehung Lager zu Verteilzentrum',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	LAGERNUMMER_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Lagernummer/Lagerkomplex      ',
	VERSANDSTELLE_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Ort, an dem Lieferungen bearbeitet werden. Es kann sich dabei um einen physischen Ort (z.B. ein Lager oder eine Gruppe von Laderampen) oder um eine logische Gruppierung (z.B. eine Gruppe von Personen, die für die Versandaktivitäten zuständig ist) handeln.',
	LAGERORT_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Schlüssel für die Lagerorte. Die Lagerorte sind pro Werk/Betrieb eindeutig. Aus lgort',
	LAGERSORTIMENT_ID VARCHAR(1) NOT NULL COLLATE 'en-ci' COMMENT 'Lagersortiment ID',
	DIFF_ID VARCHAR(1) NOT NULL COLLATE 'en-ci' COMMENT 'Wenn eine Lieferposition nicht vollständig beliefert werden kann, wird die Restmenge vom VZ nachgeliefert oder muss vom Markt neu bestellt werden. Diese Information wird auch als Nachlieferkennzeichen bezeichnet.',
	DAT_LIEF_SOLL DATE NOT NULL COMMENT 'Lieferdatum der Position',
	LIEF_TYP_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Klassifikation, mit der zwischen verschiedenen Arten der Lieferung unterschieden wird. Die Lieferart bestimmt, wie das System eine Lieferung bearbeitet.',
	VERTR_BELEG_TYP_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Dieses Kennzeichen liefert die Information aus welchem Vorgang dieser Vertriebsbeleg generiert wurde, z. B. wurde der Lieferschein aufgrund eines Wareneingangs generiert.',
	WG_ID NUMBER(38,0) NOT NULL COMMENT 'ID der Warengruppe',
	ARTHIERTYP_ID NUMBER(38,0) NOT NULL COMMENT 'Artikel - Hierarchie - Typ - ID: kennzeichnet, ob es sich um eine Hierarchie mit zwei- oder dreistelligen Warengruppen  handelt',
	KUNDE_ID NUMBER(38,0) NOT NULL COMMENT 'Als Format wurde bewusst Integer gewählt - ist kein Versehen',
	WG_VERKETT_LIEF NUMBER(38,0) NOT NULL COMMENT 'Die Warengruppenverkettung gibt an, welche Artikel gemeinsam auf eine Palette gepackt werden.',
	LIEF_PAL_TYP_ID VARCHAR(1) NOT NULL COLLATE 'en-ci' COMMENT 'Der Palettentyp einer Lieferung kennzeichnet, ob es sich um eine Ganzpalettenlieferung, Mischpalettenlieferung, Lieferung je Markt etc. handelt.',
	LIEF_PAL_TYP_DWH_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'Abgeleiteter Palettentyp (6 wird in 61 und 64 unterteilt)',
	MANDANT_ID_KUNDE NUMBER(38,0) NOT NULL COMMENT 'Der Kunde kann zu einem anderen Mandanten als der WUP gehoeren, z.Bsp. Lager aus CZ beliefert Markt in SK',
	WERBEWARE_ID VARCHAR(1) NOT NULL COLLATE 'en-ci' COMMENT 'Aus besch_lief: Wenn die Bestellart eine Werbebestellart ist. Wertevorrat: W = Werbung, N = Normalware, B = Beides W und N, S = Schnellschuss.',
	BESTELLART_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Durch die Einkaufsbelegart kann man z.B. zwischen einer Bestellung, einer Anfrage und einem Lieferplan unterscheiden.',
	HU_STATUS_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Bewegungsstatus der Handling Unit',
	DISPONENT_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Disponent ID',
	ANZAHL_POSITION NUMBER(38,0) COMMENT 'Anzahl der Positionen in der besch_lief_det',
	ANZAHL_POSITION_CHARG_SPLIT NUMBER(38,0) COMMENT 'Anzahl Lieferpositionen (mit Chargensplit)',
	ANZAHL_PACKSTUECK_ANZPK NUMBER(38,0) NOT NULL COMMENT 'Aggregation der Gesamtanzahl der Packstücke für alle Positionen der Lieferung',
	ANZAHL_PACKSTUECK_HU NUMBER(38,0) NOT NULL COMMENT 'Anzahl Packstück in Handling Unit',
	BRTVOL_LADUNG NUMBER(18,3) NOT NULL COMMENT 'Bruttovolumen Ladung',
	BRTVOL_LADUNG_GEDECKELT NUMBER(18,3) NOT NULL COMMENT 'Volumen der Ladung in Litern. Wird aud handling_unit.vol_ladung errechnet - Deckelung des Volumen der einzelnen HU auf max. 2304 cdm',
	MENGE_LIEF_SOLL_KOLLI NUMBER(18,3) COMMENT 'Die Soll-Liefermenge dient dazu, die ursprüngliche Liefermenge einer Aus- oder Anlieferung festzuhalten. Sie bezieht sich auf die Mengeneinheit der Liefermenge (LFIMG). Es handelt sich hier um Kolli!  ',
	MENGE_LIEF_IST_KOLLI NUMBER(18,3) COMMENT 'Liefermenge in Kolli',
	MENGE_LIEF_SOLL_BME NUMBER(18,3) COMMENT 'Die Soll-Liefermenge dient dazu, die ursprüngliche Liefermenge einer Aus- oder Anlieferung festzuhalten. Sie ist berechnet (redundante Speicherung) und in Bestellmengeneinheit dargestellt.',
	MENGE_LIEF_IST_BME NUMBER(18,3) COMMENT 'Menge der Lieferposition, ausgedrückt in Verkaufsmengeneinheiten aus lfimg.',
	MENGE_LIEF_SOLL_PAL NUMBER(18,3) COMMENT 'Soll-Liefermenge in PAL',
	MENGE_LIEF_IST_PAL NUMBER(18,3) COMMENT 'Ist-Liefermenge in PAL',
	ANZAHL_STELLPLATZ_EWM_EXT_PARENT NUMBER(9,2) COMMENT 'Anz. Stellpatz (parent HU)',
	ANZAHL_STELLPLATZ_EWM NUMBER(9,2) COMMENT 'Stellplatzfaktor',
	VK_NETTO_LIEF_IST NUMBER(18,4) COMMENT 'Liefermenge Ist bewertet mit dem Verkaufspreis minus MehrWertSteuer. Redundant abgelegt zur Performancesteigerung',
	VK_NETTO_LIEF_SOLL NUMBER(18,4) COMMENT 'Liefermenge soll bewertet mit dem Verkaufspreis minus MehrWertSteuer. Redundant abgelegt zur Performancesteigerung',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TRANSPORTSORTIMENT_ID VARCHAR(2) COLLATE 'en-ci' COMMENT 'Transportsortiment ID - concatenation of  Lagersortiment IDs that should be put on the same truck for transportation (for example 27 means Lagersortiment ID 2 and Lagersortiment ID 7 are transported together)',
	WG_VERKETT_FG NUMBER(38,0) NOT NULL COMMENT 'Flag. Zeigt an, ob eine Warengruppenverkettung existiert. Aus dem Feld zzlvwgrvkhier_kz',
	NTVOL_LADUNG NUMBER(18,3) COMMENT 'Netto-Ladungsgvolumen der HU',
	NTVOL_LADUNG_GEDECKELT NUMBER(18,3) COMMENT 'Netto-Ladungsgvolumen der HU (gedeckelt)',
	MENGE_GEFAHRGUT NUMBER(7,2) COMMENT 'Menge Gefahrgut',
	WRG_ID VARCHAR(3) COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR',
	BRTVOL_HU_OA NUMBER(18,3) COMMENT 'Brutto-Ladungsvolumen der HU ohne das Volumen der aufgepackten Palette',
	NTVOL_HU_OA NUMBER(18,3) COMMENT 'Netto-Ladungsvolumen der HU ohne das Volumen der aufgepackten Palette',
	BRTVOL_HU_GEDECKELT_OA NUMBER(18,3) COMMENT 'Brutto-Ladungsvolumen der HU ohne das Volumen der aufgepackten Palette (gedeckelt auf 2304 cdm)',
	NTVOL_HU_GEDECKELT_OA NUMBER(18,3) COMMENT '''Netto-Ladungsvolumen der HU ohne das Volumen der aufgepackten Palette (gedeckelt auf 2304 cdm)',
	BRTGEW_HU NUMBER(18,3) COMMENT 'Brutto-Gewicht der HU',
	NTGEW_HU NUMBER(18,3) COMMENT 'Netto-Gewicht der HU',
	BRTGEW_HU_OA NUMBER(18,3) COMMENT 'Brutto-Gewicht der HU ohne das Volumen der aufgepackten Palette',
	NTGEW_HU_OA NUMBER(18,3) COMMENT 'Netto-Gewicht der HU ohne das Volumen der aufgepackten Palette',
	MENGE_LIEF_IST_KOLLI_HU NUMBER(18,3) COMMENT 'Liefermenge in Kolli auf HU-Ebene',
	AUSLIEFERUNGSGRUPPE_ID VARCHAR(4) COMMENT 'Auslieferungsgruppe aus ZLF_AUSLFEL',
	constraint PK_BESCH_LIEF_WA_WG_SUM primary key (MANDANT_ID, WUP_ID, NB_ID, LAGERNUMMER_ID, VERSANDSTELLE_ID, LAGERORT_ID, LAGERSORTIMENT_ID, DIFF_ID, DAT_LIEF_SOLL, LIEF_TYP_ID, VERTR_BELEG_TYP_ID, WG_ID, ARTHIERTYP_ID, KUNDE_ID, WG_VERKETT_LIEF, LIEF_PAL_TYP_ID, LIEF_PAL_TYP_DWH_ID, MANDANT_ID_KUNDE, WERBEWARE_ID, BESTELLART_ID, HU_STATUS_ID, DISPONENT_ID)
)COMMENT='Warenausgangs-Positionen auf Ebene Warengruppe'
;
